begin;
set local role service_role;
do $$
declare u uuid:='7a23b121-c29c-4513-8a26-d7822f04149d'; stranger uuid:='cf55a73e-63ad-405b-ba7e-db7ffd95dcff';
 a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); d uuid:=gen_random_uuid(); admin_id uuid:='adb6a08e-1a28-4b41-8dde-addd9c06f915'; test_id text:='__team_test_'||gen_random_uuid(); empty_id text:='__team_empty_test_'||gen_random_uuid(); result jsonb; state jsonb; people jsonb; fail boolean; bulk jsonb;
begin
 result:=public.stockcount_team('init',u,test_id,a,jsonb_build_object('id',test_id,'store','APAR','date','2026-10-23','label','TESTE TEMPORARIO','kind','CONTAGEM','status','EM ANDAMENTO','responsible','João'));
 if result->>'responsible'<>'João' then raise exception 'init/name failed'; end if;
 fail:=false;begin perform public.stockcount_team('join',u,test_id,gen_random_uuid(),'{"responsible":"Ana1"}');exception when others then fail:=true;end;if not fail then raise exception 'digits accepted';end if;
 fail:=false;begin perform public.stockcount_team('join',u,test_id,gen_random_uuid(),'{"responsible":"A n a"}');exception when others then fail:=true;end;if not fail then raise exception 'short name accepted';end if;
 result:=public.stockcount_team('join',u,test_id,b,'{"responsible":"Maria"}');
 result:=public.stockcount_team('list',u,null,null,'{"store":"APAR"}');
 if not exists(select 1 from jsonb_array_elements(result) x where x->>'id'=test_id) then raise exception 'active collaborative count missing from shared device list';end if;
 state:=jsonb_build_object('requestId','test-request-0001','participantVersion',0,'counts',jsonb_build_array(jsonb_build_object('ean','000123','quantity',2,'description','Produto A','brand','MARCA','lastScannedAt','2026-10-23T12:00:00Z')),'defects','[]'::jsonb);
 result:=public.stockcount_team('save',u,test_id,a,state);
 if (result->>'participantVersion')::int<>1 then raise exception 'version not incremented';end if;
 result:=public.stockcount_team('save',u,test_id,a,state);
 if (result->>'participantVersion')::int<>1 then raise exception 'duplicate reprocessed';end if;
 fail:=false;begin perform public.stockcount_team('save',u,test_id,a,jsonb_set(state,'{counts,0,quantity}','7'));exception when others then fail:=true;end;if not fail then raise exception 'changed same packet accepted';end if;
 result:=public.stockcount_team('save',u,test_id,b,jsonb_set(state,'{requestId}','"test-request-0002"'));
 people:=public.stockcount_team_share_people(test_id);
 if jsonb_array_length(people)<>2 or (select x->>'responsible' from jsonb_array_elements(people) x where x->>'responsible'='João') is null
  or (select (x#>>'{counts,0,quantity}')::int from jsonb_array_elements(people) x where x->>'responsible'='Maria')<>2 then raise exception 'per-responsible share breakdown failed';end if;
 if people->0 ? 'id' then raise exception 'share view exposed participant capability';end if;
 result:=public.stockcount_team_snapshot(test_id);
 if (result#>>'{counts,0,quantity}')::int<>4 then raise exception 'two people did not sum';end if;
 result:=public.stockcount_team_snapshot(test_id,a);
 if (result#>>'{counts,0,quantity}')::int<>2 or (result#>>'{peers,counts,0,quantity}')::int<>2 then raise exception 'own vs peers isolation failed';end if;
 if result->'participants'->0 ? 'id' then raise exception 'peer capability exposed';end if;
 fail:=false;begin perform public.stockcount_team('read',stranger,test_id,a);exception when others then fail:=true;end;if not fail then raise exception 'cross-store read allowed';end if;
 fail:=false;begin perform public.stockcount_team('save',u,test_id,a,jsonb_set(state,'{requestId}','"test-request-stale"'));exception when others then fail:=true;end;if not fail then raise exception 'stale snapshot accepted';end if;
 -- Correction affects only João; Maria keeps 2.
 state:=jsonb_set(jsonb_set(jsonb_set(state,'{requestId}','"test-correction-001"'),'{participantVersion}','1'),'{counts,0,quantity}','1');
 result:=public.stockcount_team('finish',u,test_id,a,state);
 if result->>'status'='FINALIZADA' then raise exception 'finalized with other participant pending';end if;
 result:=public.stockcount_team_snapshot(test_id);
 if (result#>>'{counts,0,quantity}')::int<>3 then raise exception 'correction overwrote peer';end if;
 -- A device recovers 5,000 distinct products plus a defect, one stable snapshot per contribution.
 select jsonb_agg(jsonb_build_object('ean',lpad(n::text,13,'0'),'quantity',1,'description','Produto '||n,'brand','MARCA','lastScannedAt','2026-10-23T12:30:00Z')) into bulk from generate_series(1,5000) n;
 state:=jsonb_build_object('requestId','test-five-thousand','participantVersion',1,'counts',bulk,'defects',jsonb_build_array(jsonb_build_object('ean','000123','quantity',1,'description','Defeito','brand','MARCA')));
 result:=public.stockcount_team('finish',u,test_id,b,state);
 if result->>'status'<>'FINALIZADA' or jsonb_array_length(result->'counts')<>5000 then raise exception '5000/finalization failed';end if;
 result:=public.stockcount_team('finish',u,test_id,b,state);
 if (result->>'participantVersion')::int<>2 then raise exception 'lost finish response not idempotent';end if;
 result:=public.stockcount_team_snapshot(test_id);
 if jsonb_array_length(result->'counts')<>5001 or (result#>>'{defects,0,quantity}')::int<>1 then raise exception 'combined 5000/defect lost';end if;
 fail:=false;begin perform public.stockcount_team_manage_participant(test_id,b,stranger,'clear');exception when others then fail:=true;end;if not fail then raise exception 'non-admin cleared a participant';end if;
 result:=public.stockcount_team_admin_snapshot(test_id,admin_id);
 if not exists(select 1 from jsonb_array_elements(result->'participants') x where x->>'id'=b::text and x->>'responsible'='Maria') then raise exception 'ADM snapshot missing participant ID';end if;
 result:=public.stockcount_team_manage_participant(test_id,b,admin_id,'clear');
 if result->>'status'<>'EM ANDAMENTO' or jsonb_array_length(result->'counts')<>1 or jsonb_array_length(result->'defects')<>0 or (result#>>'{counts,0,quantity}')::int<>1 then raise exception 'admin clear did not isolate the selected participant';end if;
 if not exists(select 1 from jsonb_array_elements(result->'participants') x where x->>'id'=b::text and x->>'done'='false' and (x->>'units')::int=0) then raise exception 'cleared participant was not reset';end if;
 state:=public.stockcount_team_snapshot(test_id);
 if (state->'participants'->0 ? 'id') or (state->'participants'->1 ? 'id') then raise exception 'regular participant snapshot exposed IDs';end if;
 result:=public.stockcount_team_manage_participant(test_id,b,admin_id,'finish');
 if result->>'status'<>'FINALIZADA' or jsonb_array_length(result->'counts')<>1 or (result#>>'{counts,0,quantity}')::int<>1 then raise exception 'admin finish lost another participant or failed to finalize';end if;
 -- An empty participant must not clear another participant's products when finishing.
 result:=public.stockcount_team('init',u,empty_id,c,jsonb_build_object('id',empty_id,'store','APAR','date','2026-10-23','label','TESTE VAZIO','kind','CONTAGEM','status','EM ANDAMENTO','responsible','Carlos'));
 result:=public.stockcount_team('join',u,empty_id,d,'{"responsible":"Maria"}');
 state:=jsonb_build_object('requestId','empty-writer-0001','participantVersion',0,'counts',jsonb_build_array(jsonb_build_object('ean','000777','quantity',5,'description','Produto compartilhado','brand','MARCA')),'defects','[]'::jsonb);
 result:=public.stockcount_team('save',u,empty_id,c,state);
 result:=public.stockcount_team('finish',u,empty_id,d,jsonb_build_object('requestId','empty-finisher-001','participantVersion',0,'counts','[]'::jsonb,'defects','[]'::jsonb));
 if result->>'status'='FINALIZADA' then raise exception 'finished while the product owner was still counting';end if;
 result:=public.stockcount_team_snapshot(empty_id);
 if (result#>>'{counts,0,quantity}')::int<>5 then raise exception 'empty participant erased another participant products';end if;
 state:=jsonb_build_object('requestId','empty-writer-fin-01','participantVersion',1,'counts',jsonb_build_array(jsonb_build_object('ean','000777','quantity',5,'description','Produto compartilhado','brand','MARCA')),'defects','[]'::jsonb);
 result:=public.stockcount_team('finish',u,empty_id,c,state);
 if result->>'status'<>'FINALIZADA' or (result#>>'{counts,0,quantity}')::int<>5 then raise exception 'final count lost products after empty participant finish';end if;
 result:=public.stockcount_team('requestDelete',u,empty_id,d,'{}');
 if result->>'deleteStatus'<>'PENDENTE' then raise exception 'delete request was not recorded';end if;
 state:=public.stockcount_team('list',u,null,null,'{"history":true,"store":"APAR"}');
 if exists(select 1 from jsonb_array_elements(state) x where x->>'id'=empty_id) then raise exception 'pending deletion is still visible to the store';end if;
 state:=public.stockcount_team('list',admin_id,null,null,'{"history":true,"store":"APAR"}');
 if not exists(select 1 from jsonb_array_elements(state) x where x->>'id'=empty_id) then raise exception 'ADM cannot see pending deletion for review';end if;
 result:=public.stockcount_team('resolveDelete',admin_id,empty_id,d,jsonb_build_object('approve',true,'reviewVersion',(result->>'version')::bigint));
 if result->>'deleted'<>'true' then raise exception 'approved deletion did not create a tombstone';end if;
 if exists(select 1 from public.stockcount_team_counts where id=empty_id and not deleted) then raise exception 'approved deletion not hidden';end if;
 if exists(select 1 from information_schema.role_table_grants where table_name in ('stockcount_team_counts','stockcount_team_people') and grantee in ('anon','authenticated','PUBLIC')) then raise exception 'tables exposed';end if;
 raise notice 'PASS: names, replay, store isolation, admin-only person clear/finish, private participant IDs, 5000 rows + defects';
end $$;
rollback;
